import { Link, Outlet } from "react-router-dom";
import "./Home.css";

function Home() {
  return (
    <div className="container">
      <nav className="navi">
        <ul className="list-par">
          <li className="li-child">
            <Link to="/">Home</Link>
          </li>
          <li className="li-child">
            <Link to="/">Contact</Link>
          </li>
          <li className="li-child">
            <Link to="/about">About</Link>
          </li>
          <li className="li-child">
            <Link to="/login">Login</Link>
          </li>
        </ul>
      </nav>
      <Outlet />
    </div>
  );
}

export default Home;
